DROP TABLE IF EXISTS `ai_literacy_item`;
CREATE TABLE `ai_literacy_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `dimension` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AI素养维度',
  `stage` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学段',
  `grade_min` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '最低年级',
  `grade_max` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '最高年级',
  `performance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学段表现',
  `standard_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '对应课程标准',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '说明',
  `embedding_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '向量ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ai_literacy_dimension`(`dimension` ASC) USING BTREE,
  INDEX `idx_ai_literacy_stage_grade`(`stage` ASC, `grade_min` ASC, `grade_max` ASC) USING BTREE,
  INDEX `idx_ai_literacy_standard_id`(`standard_id` ASC) USING BTREE,
  INDEX `idx_ai_literacy_embedding_key`(`embedding_key` ASC) USING BTREE,
  CONSTRAINT `fk_ai_literacy_standard` FOREIGN KEY (`standard_id`) REFERENCES `curriculum_standard` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 3004 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI素养框架表' ROW_FORMAT = Dynamic;

