DROP TABLE IF EXISTS `artifact`;
CREATE TABLE `artifact`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `artifact_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'LESSON_PLAN/WORKSHEET',
  `content_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'HTML内容',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'DOCX文件',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `resource_version_id` bigint UNSIGNED NULL DEFAULT NULL,
  `file_format` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `file_size` bigint UNSIGNED NULL DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_artifact_project_type`(`project_id` ASC, `artifact_type` ASC, `version` ASC) USING BTREE,
  INDEX `idx_artifact_resource_version`(`resource_version_id` ASC) USING BTREE,
  CONSTRAINT `fk_artifact_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
