-- ----------------------------
-- Table structure for course_project
-- ----------------------------
DROP TABLE IF EXISTS `course_project`;
CREATE TABLE `course_project`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '项目ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '所属用户',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `topic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '教学主题',
  `project_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NEW_TOPIC/OPTIMIZE_EXISTING/TEXTBOOK_ADAPTATION',
  `grade` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '年级',
  `class_hours` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '课时',
  `student_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'BEGINNER/GENERAL/ADVANCED',
  `ai_access_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'TEACHER_DEMO/GROUP/INDIVIDUAL',
  `devices_json` json NULL COMMENT '教学设备',
  `constraints_json` json NULL COMMENT '教学约束',
  `additional_requirements` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '其他要求',
  `workflow_state` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '当前工作流状态',
  `stale_sections_json` json NULL COMMENT '已失效下游模块',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  `student_experience` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `class_size` smallint UNSIGNED NULL DEFAULT NULL,
  `lesson_minutes` smallint UNSIGNED NULL DEFAULT NULL,
  `context_diagnosis_json` json NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_course_project_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_course_project_workflow_state`(`workflow_state` ASC) USING BTREE,
  CONSTRAINT `fk_course_project_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1018 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程设计项目主表' ROW_FORMAT = Dynamic;

