INSERT INTO `course_project` VALUES (1011, 1, '123', '123', 'NEW_TOPIC', 3, 3, 'GENERAL', 'INDIVIDUAL', '[\"PROJECTOR\"]', '[\"LIMITED_DEVICES\"]', '123', 'OBJECTIVE_CONFIRMED', '[\"PEDAGOGY\", \"ASSESSMENT\", \"ACTIVITY\", \"QUALITY\", \"ARTIFACT\"]', '2026-09-06 17:01:37', '2026-09-06 17:02:17', NULL, NULL, NULL, NULL, NULL, 0);
INSERT INTO `course_project` VALUES (1012, 1, 'aa', 'aa', 'NEW_TOPIC', 2, 1, 'GENERAL', 'GROUP', '[\"TABLET\"]', '[\"LIMITED_TIME\"]', '暂无', 'PEDAGOGY_PENDING', '[\"OBJECTIVE\", \"PEDAGOGY\", \"QUALITY\", \"ARTIFACT\"]', '2026-09-06 18:27:26', '2026-09-07 17:33:49', NULL, '没有', 42, 40, '{\"constraints\": [\"课时仅40分钟，时间紧张。\", \"班级人数较多，组织管理与个别指导压力大。\", \"学生零基础，起点水平不明确。\", \"“aa”主题未界定，备课资源与方向不足。\", \"仅有平板可用，且未必能有效用于全员同步练习。\"], \"coreProblem\": \"课题/话题“aa”过于模糊，缺少明确的学习对象和范围，难以设计聚焦的课堂活动与评估。\", \"existingFoundation\": \"几乎没有与“aa”相关的已知先备知识或学习经历。\", \"learningDifficulties\": [\"因主题不明确，学生难以建立学习目标与意义感，注意力易分散。\", \"在缺少清晰示例与定义的情况下，理解与识别“aa”的基本特征存在困难。\", \"大班额条件下，学生表达与参与机会受限，影响对“aa”的理解与反馈。\"]}', 0);
INSERT INTO `course_project` VALUES (1013, 1, 'AI是什么', '认识AI', 'NEW_TOPIC', 3, 1, 'BEGINNER', 'TEACHER_DEMO', '[\"COMPUTER\"]', '[\"LIMITED_TIME\"]', '学生没有基础', 'ASSESSMENT_CONFIRMED', '[\"PEDAGOGY\", \"ACTIVITY\", \"QUALITY\", \"ARTIFACT\"]', '2026-09-08 10:59:35', '2026-09-08 14:59:14', NULL, NULL, NULL, NULL, NULL, 0);

-- ----------------------------
-- Table structure for curriculum_standard
-- ----------------------------
DROP TABLE IF EXISTS `curriculum_standard`;
CREATE TABLE `curriculum_standard`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '标准ID',
  `standard_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准名称',
  `stage` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学段',
  `grade_min` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '最低年级',
  `grade_max` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '最高年级',
  `core_competency` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '核心素养',
  `content_topic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内容主题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准内容',
  `performance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学业表现',
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源',
  `source_page` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '页码',
  `embedding_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'FAISS向量ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_curriculum_standard_stage_grade`(`stage` ASC, `grade_min` ASC, `grade_max` ASC) USING BTREE,
  INDEX `idx_curriculum_standard_topic`(`content_topic` ASC) USING BTREE,
  INDEX `idx_curriculum_standard_embedding_key`(`embedding_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2003 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程标准知识表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of curriculum_standard
-- ----------------------------
INSERT INTO `curriculum_standard` VALUES (2001, 'DEMO课程标准条目A（非真实课标）', 'PRIMARY', 4, 6, '信息判断与数字素养', '信息真实性与可靠性判断', 'DEMO：学生在数字化学习活动中能够比较不同来源的信息，并尝试依据证据判断信息是否可靠。', 'DEMO：能够说明判断某条信息可信或不可信的至少一个依据。', 'DEMO_STANDARD_NOT_REAL', 'N/A', 'std_demo_2001', '2026-08-25 15:00:35');
INSERT INTO `curriculum_standard` VALUES (2002, 'DEMO课程标准条目B（非真实课标）', 'PRIMARY', 4, 6, '问题解决与责任意识', '数字工具使用', 'DEMO：学生能够在教师指导下使用数字工具解决问题，并关注工具输出的局限。', 'DEMO：能够在使用数字工具后说明仍需人工检查的内容。', 'DEMO_STANDARD_NOT_REAL', 'N/A', 'std_demo_2002', '2026-08-25 15:00:35');

-- ----------------------------
-- Table structure for decision_log
-- ----------------------------
DROP TABLE IF EXISTS `decision_log`;
CREATE TABLE `decision_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `decision_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OBJECTIVE/PEDAGOGY/ASSESSMENT',
  `biz_id` bigint UNSIGNED NOT NULL COMMENT '业务ID',
  `ai_proposal_json` json NULL COMMENT 'AI原建议',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ACCEPT/REVISE/REJECT',
  `teacher_revision_json` json NULL COMMENT '教师修改',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_decision_log_project_type`(`project_id` ASC, `decision_type` ASC) USING BTREE,
  INDEX `idx_decision_log_biz`(`decision_type` ASC, `biz_id` ASC) USING BTREE,
  CONSTRAINT `fk_decision_log_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 11074 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教师认知锚点决策日志' ROW_FORMAT = Dynamic;

