-- ----------------------------
-- Table structure for design_evidence_link
-- ----------------------------
DROP TABLE IF EXISTS `design_evidence_link`;
CREATE TABLE `design_evidence_link`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OBJECTIVE/PEDAGOGY/ACTIVITY/ASSESSMENT',
  `biz_id` bigint UNSIGNED NOT NULL COMMENT '对应业务ID',
  `evidence_id` bigint UNSIGNED NOT NULL COMMENT 'Evidence ID',
  `principle` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '教学原则',
  `decision_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '当前教学决策',
  `support_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUPPORTED' COMMENT 'SUPPORTED/PARTIAL',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_design_evidence_project_biz`(`project_id` ASC, `biz_type` ASC, `biz_id` ASC) USING BTREE,
  INDEX `idx_design_evidence_evidence`(`evidence_id` ASC) USING BTREE,
  CONSTRAINT `fk_design_evidence_evidence` FOREIGN KEY (`evidence_id`) REFERENCES `evidence_card` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_design_evidence_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 10006 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教学设计—研究证据关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of design_evidence_link
-- ----------------------------
INSERT INTO `design_evidence_link` VALUES (10001, 1001, 'OBJECTIVE', 6002, 5002, '评价信息可信度需要学生实际执行多来源核验。', '目标2要求学生使用至少两个来源核验AI生成内容。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10002, 1001, 'ACTIVITY', 8001, 5001, '学生在咨询AI前先形成自己的初步判断。', '活动1先要求学生独立判断，再进入AI互动。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10003, 1001, 'ACTIVITY', 8003, 5002, '多来源信息核验需要保留来源和证据记录。', '活动3要求学生填写“主张—来源—证据—判断”记录。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10004, 1001, 'ACTIVITY', 8004, 5003, '协作比较应围绕证据和理由展开。', '活动4中教师使用“你的证据是什么？”进行追问。', 'PARTIAL', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10005, 1001, 'ASSESSMENT', 9002, 5002, '评价任务应要求学生展示实际核验过程。', '评价2要求提交来源、关键证据和最终可信度判断。', 'SUPPORTED', '2026-08-25 15:00:35');

-- ----------------------------
-- Table structure for evidence_card
-- ----------------------------
DROP TABLE IF EXISTS `evidence_card`;
CREATE TABLE `evidence_card`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Evidence ID',
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文献题目',
  `authors` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '作者',
  `year` smallint UNSIGNED NULL DEFAULT NULL COMMENT '年份',
  `topic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '研究主题',
  `education_stage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学段',
  `participants` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '研究对象',
  `research_design` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '研究设计',
  `sample_size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '样本',
  `main_finding` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '主要发现',
  `effect_direction` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'POSITIVE/MIXED/UNCERTAIN',
  `boundary_condition` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '适用条件',
  `limitation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '局限',
  `evidence_strength` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'STRONG/MODERATE/PRELIMINARY',
  `teaching_implication` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '教学启示',
  `source_document` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源',
  `source_page` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '页码',
  `source_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原始支持文本',
  `search_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '检索文本',
  `embedding_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'FAISS索引ID',
  `review_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT 'REVIEWED/DRAFT',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `recommended_strategies_json` json NULL,
  `implementation_conditions_json` json NULL,
  `source_metadata_json` json NULL,
  `card_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `research_analysis_id` bigint UNSIGNED NULL DEFAULT NULL,
  `confirmed_by` bigint UNSIGNED NULL DEFAULT NULL,
  `confirmed_at` datetime NULL DEFAULT NULL,
  `project_id` bigint UNSIGNED NULL DEFAULT NULL,
  `source_file_id` bigint UNSIGNED NULL DEFAULT NULL,
  `source_chunk_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `source_retrieval_score` float NULL DEFAULT NULL,
  `source_message_id` bigint UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_evidence_project_source_chunk`(`project_id` ASC, `source_chunk_id` ASC) USING BTREE,
  INDEX `idx_evidence_stage`(`education_stage` ASC) USING BTREE,
  INDEX `idx_evidence_review_strength`(`review_status` ASC, `evidence_strength` ASC) USING BTREE,
  INDEX `idx_evidence_year`(`year` ASC) USING BTREE,
  INDEX `idx_evidence_embedding_key`(`embedding_key` ASC) USING BTREE,
  INDEX `fk_evidence_card_source_file`(`source_file_id` ASC) USING BTREE,
  INDEX `idx_evidence_source_message`(`source_message_id` ASC) USING BTREE,
  CONSTRAINT `fk_evidence_card_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_evidence_card_source_file` FOREIGN KEY (`source_file_id`) REFERENCES `research_resource` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_evidence_card_source_message` FOREIGN KEY (`source_message_id`) REFERENCES `research_chat_message` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 5007 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教育研究证据卡' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of evidence_card
-- ----------------------------
INSERT INTO `evidence_card` VALUES (5001, 'DEMO Evidence A: Prior thinking before AI consultation', 'DEMO AUTHORS', 2026, 'AI信息核验与学生先行思考', 'PRIMARY', 'DEMO小学生样本', 'DEMO_QUASI_EXPERIMENT', 'N=60 (DEMO)', 'DEMO：在咨询AI前先形成初步观点的学生，更容易在后续讨论中比较AI建议与原有判断。', 'POSITIVE', '仅用于当前Demo逻辑验证。', '非真实研究，不可用于正式教学或论文引用。', 'PRELIMINARY', 'DEMO：让学生先表达自己的判断，再查看AI回答。', 'DEMO_SOURCE_NOT_REAL', 'N/A', 'DEMO SOURCE TEXT：学生先形成自己的判断，再接触AI建议，有助于后续比较与修正。', '学生 先形成观点 AI 信息核验 比较 修正 DEMO', 'evi_demo_5001', 'REVIEWED', '2026-08-25 15:00:35', NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5002, 'DEMO Evidence B: Multiple-source verification', 'DEMO AUTHORS', 2026, '多来源信息核验', 'PRIMARY', 'DEMO小学生样本', 'DEMO_CLASSROOM_STUDY', 'N=48 (DEMO)', 'DEMO：要求学生使用两个以上来源进行核验，可以增加对信息依据的关注。', 'POSITIVE', '需要教师提供可访问的信息来源。', '非真实研究，不可作为正式研究证据。', 'PRELIMINARY', 'DEMO：评价任务应要求学生展示核验来源和判断理由。', 'DEMO_SOURCE_NOT_REAL', 'N/A', 'DEMO SOURCE TEXT：多来源核验任务要求学生记录来源并说明不同来源是否一致。', '多来源 核验 证据 来源 判断 DEMO', 'evi_demo_5002', 'REVIEWED', '2026-08-25 15:00:35', NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5003, 'DEMO Evidence C: Collaborative comparison of AI outputs', 'DEMO AUTHORS', 2026, '协作比较AI输出', 'PRIMARY', 'DEMO小组学习样本', 'DEMO_MIXED_METHODS', 'N=54 (DEMO)', 'DEMO：同伴之间比较不同AI回答时，教师追问证据可帮助学生避免仅凭表面流畅度判断。', 'MIXED', '需要明确的比较标准和教师追问。', '非真实研究，不可作为正式研究证据。', 'PRELIMINARY', 'DEMO：在小组讨论中加入“你的证据是什么”的追问。', 'DEMO_SOURCE_NOT_REAL', 'N/A', 'DEMO SOURCE TEXT：协作比较需要围绕证据展开，而不是只比较AI回答是否听起来更完整。', '协作 AI回答 比较 证据 教师追问 DEMO', 'evi_demo_5003', 'REVIEWED', '2026-08-25 15:00:35', NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5005, 'DEMO研究：小学高年级学生AI信息核验能力培养——多来源比较与证据判断', 'DEMO研究团队', 2026, '生成式AI信息核验与证据判断', 'PRIMARY', '小学五、六年级学生，DEMO样本84人', 'DEMO_QUASI_EXPERIMENT', 'N=84 (DEMO)', 'DEMO结果显示：多来源核验、同伴证据比较以及基于证据修订判断，有助于学生更关注AI回答的信息依据；其中“先形成个人判断，再咨询AI”的安排有助于学生识别AI建议与已有证据之间的不一致。', 'POSITIVE', '适用于能够访问多个信息来源、教师能够提供证据记录支架，并预留同伴讨论时间的小学高年级课堂。', 'DEMO研究来自单一学校且干预仅4周，不可据此推断长期迁移或普遍效果；该记录仅供平台演示。', 'MODERATE', '可将课程设计为“初步判断 → 比较AI回答 → 多来源核验 → 小组说明证据 → 修订最终判断”。评价时要求学生同时提交信息来源、关键证据和接受/修改/拒绝AI建议的理由。', 'DEMO研究资源（非真实文献）', 'DEMO p.5–12', 'DEMO来源文本：学生先形成初步判断，再通过至少两个信息来源核验AI回答，并在小组中依据证据修订结论。', '小学 五年级 生成式AI 信息核验 多来源核验 证据判断 同伴讨论 修订 AI回答 DEMO', NULL, 'REVIEWED', '2026-09-03 19:26:37', '[\"先判断后咨询AI\", \"多来源信息核验\", \"同伴证据比较\", \"基于证据修订判断\"]', '[\"提供至少两个可访问的信息来源\", \"提供“主张—来源—证据—判断”记录支架\", \"预留小组讨论和观点修订时间\"]', '{\"note\": \"Synthetic demo evidence; not for academic citation.\", \"demoOnly\": true, \"mediaType\": \"application/pdf\", \"projectId\": 1001, \"resourceId\": 2, \"originalFilename\": \"DEMO_小学AI信息核验研究.pdf\"}', 'CONFIRMED', 2, 1, '2026-09-03 19:32:00', 1001, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5006, 'University students\' use of generative AI (GAI)', NULL, NULL, 'University students\' use of generative AI (GAI)', NULL, 'undergraduate and graduate students in the United States', NULL, NULL, 'Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\nNon-native English speakers use and adopt GAI more readily than native speakers.\nCompared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\nBlack students report a more positive impact of GAI on their academic performance.\nStudents with higher conscientiousness use GAI less.\nStudents who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\nStudents with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\nStudents with higher extraversion show a stronger preference for GAI over traditional resources.\nStudents with higher intellect/imagination tend to prefer traditional resources.', NULL, NULL, 'The study is limited to one-time cross-sectional survey data.', NULL, NULL, '2026-会议-Understanding University Students’ Use of Generative AI—The Roles of Demographics and Personality Traits.pdf', NULL, 'Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.', NULL, NULL, 'DRAFT', '2026-09-08 18:55:42', '[\"探究式学习\"]', '[\"30分钟\"]', '{\"sha256\": \"d9d8f68b29f0343ab2021fc49cc9b352dabf7ed25bb47e26943a261aa5dcc65a\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1012, \"size_bytes\": 382337, \"resource_id\": 7, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"2026-会议-Understanding University Students’ Use of Generative AI—The Roles of Demographics and Personality Traits.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"2026-会议-Understanding University Students’ Use of Generative AI—The Roles of Demographics and Personality Traits.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'CONFIRMED', 13, 1, '2026-09-08 18:55:51', NULL, NULL, NULL, NULL, NULL);

-- ----------------------------
-- Table structure for pedagogy_method
-- ----------------------------
DROP TABLE IF EXISTS `pedagogy_method`;
CREATE TABLE `pedagogy_method`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '教学法编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '定义',
  `suitable_objectives` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '适用目标',
  `suitable_tasks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '适用任务',
  `suitable_stage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '适用学段',
  `typical_structure` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '典型活动结构',
  `teacher_role` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '教师角色',
  `student_role` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学生角色',
  `ai_role` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'AI适合介入方式',
  `risk_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '可能问题',
  `embedding_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '向量ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pedagogy_method_code`(`code` ASC) USING BTREE,
  INDEX `idx_pedagogy_stage`(`suitable_stage` ASC) USING BTREE,
  INDEX `idx_pedagogy_embedding_key`(`embedding_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4006 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教学法知识表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pedagogy_method
-- ----------------------------
INSERT INTO `pedagogy_method` VALUES (4001, 'INQUIRY_BASED', '探究式学习', '围绕问题提出猜想、收集证据、比较解释并形成结论。', '适合需要证据判断、解释和探究的问题。', '信息核验、比较多个来源、形成证据化判断。', 'PRIMARY', '提出问题 → 初步判断 → 搜集证据 → 比较解释 → 形成结论', '组织问题情境、提供支架、追问证据。', '提出观点、搜集证据、比较并修正判断。', '提供待核验的信息、补充观点或提出挑战。', '如果AI过早给出完整答案，可能削弱学生自己的判断过程。', 'ped_demo_4001');
INSERT INTO `pedagogy_method` VALUES (4002, 'PROJECT_BASED', '项目式学习', '围绕真实项目产出组织较长周期的学习活动。', '适合综合性、成果导向目标。', '制作作品、解决真实问题、持续迭代。', 'PRIMARY', '真实问题 → 方案设计 → 制作 → 测试 → 展示', '组织项目、提供资源和反馈。', '协作完成项目并持续迭代。', '辅助资料整理、创意拓展与反馈。', '需避免AI替学生完成核心产出。', 'ped_demo_4002');
INSERT INTO `pedagogy_method` VALUES (4003, 'PROBLEM_BASED', '问题式学习', '以复杂问题作为知识学习和问题解决的组织核心。', '适合问题分析、证据应用与方案提出。', '分析案例、提出方案、解释理由。', 'PRIMARY', '问题呈现 → 知识缺口 → 自主学习 → 方案讨论 → 反思', '提供问题、促进讨论和反思。', '界定问题并共同提出方案。', '补充信息、提出反例。', '可能出现学生直接依赖AI生成解决方案。', 'ped_demo_4003');
INSERT INTO `pedagogy_method` VALUES (4004, 'SITUATED_EXPERIENTIAL', '情境体验式学习', '通过具体情境和体验任务促进理解与应用。', '适合情境判断和实践应用。', '模拟任务、角色体验、实践操作。', 'PRIMARY', '情境进入 → 体验 → 观察 → 解释 → 应用', '创设情境并组织反思。', '参与体验并解释经验。', '模拟情境或提供反馈。', '需要保证体验之后有充分反思。', 'ped_demo_4004');
INSERT INTO `pedagogy_method` VALUES (4005, 'COLLABORATIVE', '协作学习', '通过同伴互动、观点比较和共同产出促进学习。', '适合需要多视角比较与共同判断的目标。', '小组讨论、同伴核验、共同规则建构。', 'PRIMARY', '个人思考 → 小组分享 → 证据比较 → 协商 → 共同产出', '组织分组、促进公平参与。', '分享观点、比较证据、协商结论。', '提供挑战观点或作为额外信息源。', '需要防止少数成员或AI主导小组判断。', 'ped_demo_4005');

-- ----------------------------
-- Table structure for project_activity
-- ----------------------------
DROP TABLE IF EXISTS `project_activity`;
CREATE TABLE `project_activity`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '活动ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `sequence_no` int UNSIGNED NOT NULL COMMENT '顺序',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '活动名称',
  `duration` int UNSIGNED NOT NULL COMMENT '分钟',
  `teacher_action` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '教师行为',
  `student_action` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学生行为',
  `ai_role` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE' COMMENT 'AI角色',
  `dominant_actor` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STUDENT' COMMENT '主导主体',
  `objective_refs_json` json NULL COMMENT '对应目标',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `core_task` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `assessment_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `scaffolds_json` json NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_activity_project_seq`(`project_id` ASC, `sequence_no` ASC) USING BTREE,
  INDEX `idx_project_activity_ai_role`(`ai_role` ASC) USING BTREE,
  CONSTRAINT `fk_project_activity_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 8014 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目教学活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_activity
-- ----------------------------
INSERT INTO `project_activity` VALUES (8001, 1001, 1, '先判断：这条AI回答可信吗？', 10, '呈现一条包含可疑信息的固定Demo AI回答，不立即给出正确答案。', '个人阅读并标出自己认为需要核验的内容，写下初步判断。', 'TEACHER_DEMO', 'STUDENT', '[6001, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8002, 1001, 2, '向AI追问并记录新信息', 15, '提示学生记录AI补充了什么，而不是直接采纳答案。', '向AI提出澄清问题，并记录AI增加、挑战或改变了哪些信息。', 'STUDENT_QUERY', 'STUDENT', '[6001, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8003, 1001, 3, '多来源核验', 25, '提供两个固定Demo信息来源，并示范如何记录来源差异。', '比较AI回答与两个信息来源，填写“主张—来源—证据—判断”记录。', 'EVIDENCE_SUPPORT', 'STUDENT', '[6002]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8004, 1001, 4, '小组比较与挑战', 20, '追问“你的证据是什么？”并提醒区分观点与证据。', '小组比较各自判断，对分歧点提出证据并修正结论。', 'IDEA_CHALLENGE', 'COLLABORATIVE', '[6002, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8005, 1001, 5, '形成AI信息核验规则', 10, '组织全班汇总，并明确规则仍需结合具体任务使用。', '总结至少三条核验规则，并说明哪些AI建议被接受、修改或拒绝。', 'FEEDBACK', 'COLLABORATIVE', '[6001, 6002, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8010, 1012, 1, '共同界定学习范围与提炼特征', 8, '展示三张代表性“aa”图片，引导全班提问与头脑风暴，板书关键词', '观察、举手发言提出可能特征，记录至少两条关键特征在练习本上', '在平板推送高清图片，自动高亮重复出现的特征词汇', 'STUDENT', '[6006, 6009]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '观察三个明确的“aa”示例并讨论其共有特点，形成初步定义', '口头抽查两名学生说出的两个特征，依据目标6006/6009评价表即时打勾', '[\"句型提示卡“我注意到…因为…”\", \"特征词库（颜色/形状/大小）\"]');
INSERT INTO `project_activity` VALUES (8011, 1012, 2, '正反例分类练习', 8, '分发数字卡片，示范一个正例和一个反例的判断思路', '拖拽卡片完成分类，在表格旁用一句话写出判断依据', '实时检测分类结果，对错误项弹出微提示', 'STUDENT', '[6007]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '将教师提供的六个项目分为“属于aa”和“不属于aa”两类，并写理由', '收集电子表格，检查每类≥2项且理由与特征关联，对应目标6007', '[\"T-Chart模板\", \"连接词“因为它有…所以…”\"]');
INSERT INTO `project_activity` VALUES (8012, 1012, 3, '独立创作“aa”新例子', 12, '巡视指导，提醒学生使用之前归纳的两条以上关键属性', '绘制或口述新例子，录制15秒语音说明其为何属于“aa”', '提供简易轮廓模板和颜色调色板，支持语音转文字字幕', 'STUDENT', '[6008, 6011, 6010]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '利用平板绘图工具或口头描述，设计一个符合“aa”特征的新实例并解释', '根据目标6008/6011/6010，核查作品是否体现主要特征、解释是否含≥2条属性', '[\"创作计划单\", \"词汇银行（名称/颜色/形状）\"]');
INSERT INTO `project_activity` VALUES (8013, 1012, 4, '同伴互评与反馈', 12, '组织快速轮换展示，强调礼貌倾听与积极反馈', '观看同伴作品，使用“我注意到……，因为……”口头或书写反馈并请同伴确认', '计时器管理展示节奏，自动采集反馈句子供教师查看', 'STUDENT', '[6012]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '运用指定句型给同伴的作品提出一条具体反馈', '随机抽取三条反馈录音，评估句型完整性及指向的具体特征，对应目标6012', '[\"句型提示牌\", \"互评便利贴模板\"]');

-- ----------------------------
-- Table structure for project_assessment
-- ----------------------------
DROP TABLE IF EXISTS `project_assessment`;
CREATE TABLE `project_assessment`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `objective_id` bigint UNSIGNED NOT NULL COMMENT '对应目标',
  `task_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评价任务',
  `student_evidence_json` json NULL COMMENT '学生应提供证据',
  `criteria_json` json NULL COMMENT '评价标准',
  `rationale` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '推荐理由',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ACCEPT/REVISE',
  `confirmed` tinyint NOT NULL DEFAULT 0 COMMENT '是否确认',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_assessment_project`(`project_id` ASC, `confirmed` ASC) USING BTREE,
  INDEX `idx_project_assessment_objective`(`objective_id` ASC) USING BTREE,
  CONSTRAINT `fk_project_assessment_objective` FOREIGN KEY (`objective_id`) REFERENCES `project_objective` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_project_assessment_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 9038 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目评价任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_assessment
-- ----------------------------
INSERT INTO `project_assessment` VALUES (9001, 1001, 6001, '给出一段新的固定Demo AI回答，请学生标出至少两处需要进一步核验的信息，并说明原因。', '[\"标记出的可疑信息\", \"需要核验的理由\"]', '{\"criterion1\": \"能识别需要核验的信息\", \"criterion2\": \"能够说明核验理由\"}', '直接测量学生能否识别需要核验的信息。', 'ACCEPT', 1, 1, '2026-08-25 15:00:35');
INSERT INTO `project_assessment` VALUES (9002, 1001, 6002, '学生使用至少两个固定Demo来源核验AI回答，提交来源、关键证据和最终可信度判断。', '[\"至少两个信息来源\", \"关键证据记录\", \"可信度判断及理由\"]', '{\"criterion1\": \"使用多个来源\", \"criterion2\": \"证据与判断之间存在对应关系\", \"criterion3\": \"能够解释最终判断\"}', '避免只用定义记忆题评价信息核验能力。', 'REVISE', 1, 1, '2026-08-25 15:00:35');
INSERT INTO `project_assessment` VALUES (9003, 1001, 6003, '比较“自己的初步观点—同伴意见—AI建议”，说明最终接受、修改或拒绝哪些内容及其理由。', '[\"初步观点\", \"同伴意见\", \"AI建议\", \"最终决定及理由\"]', '{\"criterion1\": \"能比较不同观点\", \"criterion2\": \"最终决定有证据或理由支撑\"}', '用于评价学生是否保留对最终判断的责任。', 'ACCEPT', 1, 1, '2026-08-25 15:00:35');
INSERT INTO `project_assessment` VALUES (9004, 1010, 6004, '围绕“111”完成一项信息判断与证据说明任务。', '[\"完成的任务记录\", \"所用信息来源或证据\", \"基于证据的判断说明\"]', '[\"目标要求的行为能够被观察\", \"证据与判断具有明确对应关系\", \"能够说明判断或修正理由\"]', '任务直接要求学生展示目标所要求的行为与证据。', NULL, 1, 1, '2026-09-06 12:00:01');
INSERT INTO `project_assessment` VALUES (9005, 1012, 6006, '在教师引导的课堂讨论中，学生口头用自己的话说明“aa”的学习范围，并明确说出至少两个“aa”的关键特征。', '[\"课堂录音或教师记录的学生发言文本，包含对“aa”范围的界定与两个关键特征的表述。\"]', '[\"能清晰界定“aa”的学习范围。\", \"能准确说出至少两个“aa”的关键特征。\", \"语言表达为学生自己的话，而非复述教师原句。\"]', '主题“aa”模糊且学生零基础，采用探究式讨论可直接观察学生是否建立基本共识，并为后续概念建构奠定语言基础。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9006, 1012, 6009, '观察教师提供的3个明确的“aa”示例后，学生独立列出至少2条共同特征，并用自己的话给出一个简单定义。', '[\"学生书面或口头回答：列出的共同特征与简单定义。\"]', '[\"从给定3例中正确提取至少2条共同特征。\", \"给出的简单定义与所列特征一致、无矛盾。\", \"使用学生自己的话表达，避免机械背诵。\"]', '有限且清晰的实例有助于二年级学生形成概念框架；通过可观察的特征列举与定义，直接评估其归纳能力。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9007, 1012, 6007, '在教师提供的结构化示例集中，学生判断并记录属于“aa”和不属于“aa”的实例各至少两个，并写出简短理由。', '[\"学生完成的分类表或答题纸，含每个判断及理由。\"]', '[\"正确识别属于“aa”的实例≥2。\", \"正确识别不属于“aa”的实例≥2。\", \"每条判断附简短理由，逻辑与“aa”特征相关。\"]', '正反例对比是澄清模糊概念的有效方式；结构化任务便于在大班额下快速收集每位学生的判断证据。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9008, 1012, 6010, '在教师提示下，学生说出或写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状等）。', '[\"学生口头清单或书写词汇列表。\"]', '[\"提供≥3个与“aa”相关的描述性基本词汇。\", \"词汇类别可包括名称/颜色/形状等，并与“aa”相符。\", \"表达清晰，能在需要时用中文解释词义。\"]', '零基础情况下，聚焦核心词汇可统一表达基础；口头或书面产出均为可直接观察的证据。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9009, 1012, 6008, '学生用平板绘制或口头描述创作一个新例子，使其符合“aa”的特征，并向同伴解释其关键属性。', '[\"平板绘图文件或口头描述录音。\", \"同伴记录的互动反馈便签/表格。\"]', '[\"创作的例子与“aa”特征一致。\", \"解释至少包含两条关键属性。\", \"表达清楚，能让同伴理解其例子为何属于“aa”。\"]', '大班额条件下，利用平板进行个别化表达提升参与度；创作与解释活动直接检验学生对“aa”的创造性理解。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9010, 1012, 6012, '当同伴展示作品时，学生使用指定句型“我注意到……，因为……”向同伴提出一条具体反馈。', '[\"同伴互评记录表，含该句型的完整使用。\"]', '[\"完整使用句型“我注意到……，因为……”。\", \"反馈内容指向作品的具体细节（如特征/颜色/形状/结构）。\", \"理由与“aa”特征或作品表现相关。\"]', '结构化句型支持二年级学生在缺乏示例和表达机会受限的情况下，进行有效同伴反馈，提高课堂互动质量。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9011, 1012, 6006, '在教师引导的课堂讨论后，每位学生用自己的话写下至少两个“aa”的关键特征，并说明为什么这些特征属于“aa”。', '[\"学生书面写出的两个关键特征\", \"对每个特征归属理由的简短解释\"]', '[\"至少写出两个与“aa”相关的关键特征\", \"用自己话表述，非照搬教师原句\", \"为每个特征提供一条简要理由\"]', '通过即时书面输出，直接检验学生是否从讨论中提炼出“aa”的范围与核心特征，符合建立基本共识的认知起点。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9012, 1012, 6009, '观察教师展示的3个明确“aa”示例，学生独立列出至少2条这些示例的共同特征，并用一句话给出“aa”的简单定义。', '[\"列出的共同特征清单\", \"一句简单定义\"]', '[\"至少列出2条跨示例的共同特征\", \"定义中包含“aa”且与所列特征一致\", \"语言简洁、二年级可理解\"]', '以有限清晰实例为基础，考察学生归纳共性并形成初步概念框架的能力，降低因主题模糊导致的理解偏差。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9013, 1012, 6007, '在教师提供的结构化示例集中，学生识别并记录至少两个属于“aa”的实例和至少两个不属于“aa”的实例，并为每个判断写出一条简单理由。', '[\"正例清单（≥2）\", \"反例清单（≥2）\", \"每条判断的简短理由\"]', '[\"正确分类：正例确实符合“aa”特征，反例不符合\", \"每条理由指向具体特征或标准\", \"书写清楚、逻辑简单连贯\"]', '通过正反例对比，评价学生初步判断与分类能力，解决因缺少清晰边界导致的混淆，巩固对“aa”的理解。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9014, 1012, 6010, '在教师引导下，学生说出或写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状等），并标注每个词汇对应的特征类别。', '[\"至少3个描述性词汇列表\", \"每个词汇对应的特征类别标注（如“颜色”“形状”）\"]', '[\"数量不少于3个\", \"词汇与“aa”的主要特征相关\", \"能正确标注每个词汇所属的特征类别\"]', '聚焦核心词汇产出，直接衡量学生是否能建立共同描述语言，为后续表达与评估奠定基础。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9015, 1012, 6008, '学生利用平板绘制一个新例子，使其符合“aa”的关键属性，并向同伴口头解释该例子为何属于“aa”（至少说明两条关键属性）。', '[\"平板绘制作品\", \"口头解释录音要点摘录\", \"同伴确认记录\"]', '[\"新例子明显体现“aa”的关键属性\", \"口头解释包含至少两条关键属性\", \"解释与图画一致，逻辑清晰\"]', '在大班额条件下，通过个别化创作与口头说明，确保每位学生的创造性理解被可视化并得到检验。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9016, 1012, 6011, '每位学生独立使用平板简易绘图工具完成一幅草图，呈现“aa”的主要特征；在全班展示时，口头说明至少1条所画特征与“aa”的关系。', '[\"完成的草图文件名或截图\", \"展示时口头说明的要点记录\"]', '[\"草图包含“aa”主要特征\", \"口头说明至少1条特征及其与“aa”的联系\", \"表达清晰、时间控制在规定范围内\"]', '在时间受限与大班额情境下，个体产出与简短分享便于教师快速评价每生的理解程度，保证全员参与。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9017, 1012, 6012, '当同伴展示作品时，学生运用指定句型“我注意到……，因为……”对其作品提出一条具体反馈，指出一个可见特征及相应的依据。', '[\"使用指定句型的完整句子\", \"被指出的具体特征与依据\"]', '[\"完整使用给定句型，结构正确\", \"反馈指向作品中的具体可见特征\", \"依据与特征之间有合理关联\"]', '通过结构化句型支持二年级学生进行有效同伴反馈，提升互动质量，并使评价过程可观察、可量化。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9018, 1012, 6006, '在教师引导的全班讨论中，围绕话题“aa”共同确定本节课的学习范围，并用自己的话列出至少两个“aa”的关键特征。', '[\"学生口头发言记录或姓名牌展示的特征清单\", \"教师记录的学生定义要点\"]', '[\"明确写出至少两条关键特征\", \"使用学生自己的语言而非照搬教师原话\", \"特征与课堂共同确定的学习范围一致\"]', '在主题模糊且零基础的情况下，通过讨论澄清范围并让学生用自己的话提炼特征，可直接观察其是否建立基本共识，避免仅记忆定义。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9019, 1012, 6009, '观察教师呈现的3个与“aa”相关的明确示例，独立列出至少2条这些示例的共同特征，并用一句简单的话给出“aa”的操作性定义。', '[\"学生写下的特征列表和一句话定义\", \"教师用红笔标注的符合/不符合特征的依据\"]', '[\"从给定3个示例中提取至少2条共同特征\", \"一句话定义能涵盖这些共同特征\", \"表述清晰、二年级可读（简短词汇与句式）\"]', '提供有限且清晰的实例有助于二年级学生建立概念框架；直接基于示例提取特征并形成简单定义，可观察其归纳能力而非记忆。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9020, 1012, 6007, '在教师提供的结构化表格中，将给定项目分成“属于aa”和“不属于aa”两类，每类至少包含两个项目，并为每个选择写一句简单理由。', '[\"分类完成的工作表照片或扫描件\", \"每项旁边的一句理由（可用口述由教师代记）\"]', '[\"“属于aa”至少2项，“不属于aa”至少2项\", \"每项都附有一句理由\", \"至少一条理由涉及核心特征或规则的运用\"]', '正例与反例对比能训练初步判断与分类能力；要求写理由可观察其是否理解边界条件，而不仅是凭直觉。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9021, 1012, 6010, '在教师给出的提示下，说出或写出至少3个用于描述“aa”的基本词汇（例如名称、颜色、形状等），并与同学交流这些词分别描述了什么。', '[\"词汇清单（手写或电子输入）\", \"同伴互评的小贴纸或简易核对表\"]', '[\"至少写出/说出3个相关词汇\", \"每个词汇能指向“aa”的某个可观察属性\", \"拼写或发音在二年级可接受范围内\"]', '在零基础与话题未界定的情况下，聚焦核心词汇可快速建立共同语言基础；通过说或写进行表达，可直接测量其词汇掌握而非辨认。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9022, 1012, 6008, '用平板绘制一幅图或用口头描述创作一个新的“aa”例子，并向同伴解释它为什么符合“aa”的关键属性。', '[\"平板绘图文件或口头描述录音\", \"同伴反馈便签：记录其解释中的关键点\"]', '[\"新作品/描述明显体现至少一条“aa”的关键属性\", \"解释中能点出“因为它具有……特征”这类理由\", \"表达清晰，能让同伴听懂/看懂\"]', '在大班额条件下，利用平板支持个别化表达，提高参与度；创作并解释能巩固对概念的理解，评估其创造性应用。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9023, 1012, 6012, '当同伴展示其创作的“aa”例子时，使用指定句型“我注意到……，因为……”提出一条具体反馈，并说明理由。', '[\"录音或教师观察记录：完整使用句型的一次反馈\", \"同伴确认收到反馈的示意（如点头或勾选）\"]', '[\"完整使用“我注意到……，因为……”句型\", \"反馈内容针对同伴作品的具体特征\", \"理由与特征相吻合，逻辑简单清晰\"]', '缺乏清晰示例及表达机会受限时，结构化句型能降低表达难度；观察其在真实互动中使用句型，可直接测量同伴反馈能力。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9024, 1012, 6006, '课堂讨论结束后，学生独立用文字或图画形式写下至少两个关于“aa”的关键特征。', '[\"学生的文字记录/图画\"]', '[\"能列出至少两个与课堂共识一致的“aa”关键特征\"]', '通过独立输出检验学生是否参与课堂讨论并形成对“aa”学习范围的共同认知，落实目标中“明确话题范围”的要求。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9025, 1012, 6009, '教师提供3个“aa”相关明确示例后，学生列出至少两条共同特征并给出一个简单定义。', '[\"学生的分析记录/书面定义\"]', '[\"能准确识别至少两个示例的共同特征\", \"定义符合“aa”基本内涵\"]', '通过实例分析检验学生是否能从有限清晰实例中提取共同特征，验证目标中“建立基本概念框架”的达成度。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9026, 1012, 6007, '教师提供5个实例（含“aa”与非“aa”各至少2个），学生分类并写出简单理由。', '[\"学生的分类结果及理由记录\"]', '[\"能正确区分至少2个“aa”实例和2个非“aa”实例\", \"理由基于“aa”关键特征\"]', '通过正反例分类检验学生初步判断与分类能力，解决因缺少清晰示例导致的理解困难，匹配目标要求。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9027, 1012, 6010, '学生口头或书面说出/写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状）。', '[\"学生的词汇列表/口头录音\"]', '[\"能列出至少3个符合“aa”核心特征的描述性词汇\"]', '聚焦核心词汇的输出，检验学生是否掌握“aa”的基础表达，为后续活动奠定共同语言基础。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9028, 1012, 6008, '学生利用平板绘制或口头描述一个符合“aa”特征的新例子，并向同伴解释其关键属性。', '[\"学生的作品/口头解释录音\"]', '[\"作品/描述符合“aa”至少一个关键特征\", \"能口头说明1条关键属性\"]', '通过创造性产出与解释，检验学生对“aa”概念的创造性理解，同时在大班额中保证个体参与。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9029, 1012, 6011, '学生独立用平板绘制一幅包含“aa”主要特征的草图，全班展示时口头说明1条所画特征。', '[\"学生的草图/口头说明录音\"]', '[\"草图包含“aa”至少一个主要特征\", \"能准确说出1条所画特征\"]', '通过个体草图与简短分享，检验每位学生对“aa”主要特征的掌握，便于教师快速评价理解程度。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9030, 1012, 6012, '当同伴展示“aa”作品时，学生运用给定句型“我注意到……，因为……”提出一条具体反馈。', '[\"学生的反馈语句记录/录音\"]', '[\"使用指定句型\", \"反馈内容具体指向同伴作品的特征\"]', '通过结构化句型的使用，检验学生是否能进行有效同伴反馈，提升课堂互动质量，匹配目标要求。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9031, 1012, 6006, '教师在白板上写下话题“aa”，学生以小组为单位进行讨论，每个小组向全班分享一个他们认为属于“aa”的关键特征，并说明理由。', '[\"课堂讨论录音记录下的学生发言片段。\", \"学生提交的关于“aa”关键特征的文字或图画定义。\"]', '[\"能够提出至少两个与“aa”相关的、合理的特征。\", \"能用自己的话清晰地解释为什么这些是“aa”的特征。\", \"理由是基于对“aa”范围的共同理解，而非个人臆测。\"]', '此评估直接测量学生参与课堂讨论并用自己的话定义“aa”特征的能力，这与目标6006的要求一致，通过协作澄清学习范围。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9032, 1012, 6009, '教师展示3个明确属于“aa”的示例（如图片或实物）。学生独立完成一份工作表，列出他们观察到的这3个示例的共同点，并根据这些共同点给出一个简单的定义。', '[\"学生填写的工作表，其中列出了至少2条共同特征。\", \"学生给出的简单定义。\"]', '[\"能够准确地从3个示例中识别出至少2条共同特征。\", \"给出的简单定义能够概括所观察到的共同特征。\", \"定义使用自己的语言，而不是简单地复述教师的讲解。\"]', '该任务要求学生基于给定的具体实例进行分析和归纳，直接评估其建立“aa”概念框架的能力，符合目标6009的要求。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9033, 1012, 6007, '教师提供一个包含多个项目的列表，其中一些属于“aa”，另一些则不属于。学生需要将它们分类，并对每一个分类选择至少一项说明理由。', '[\"学生的分类结果，其中至少有2个“是”的例子和2个“否”的例子。\", \"学生为每个例子提供的简短理由。\"]', '[\"能够正确识别至少2个“aa”的实例和2个非“aa”的实例。\", \"提供的理由是基于项目是否符合“aa”的特征，逻辑清晰。\", \"理由表述清楚，即使是简单的词语也能表达判断依据。\"]', '通过正反例对比来判断和分类，可以直接检验学生对“aa”概念的理解深度，训练其初步的判断能力，支持目标6007。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9034, 1012, 6010, '教师口头描述或展示“aa”的一个具体例子，然后提问：“我们可以用哪些词来描述它？”学生轮流回答，说出描述“aa”的基本词汇。', '[\"教师记录的学生口述词汇列表。\", \"学生在单词墙上指出或圈出的相应词汇。\"]', '[\"能够说出至少3个用于描述“aa”的基本词汇。\", \"所提词汇与“aa”相关且具有描述性（如颜色、形状、名称等）。\"]', '这个形成性评估直接衡量学生是否能聚焦于核心词汇，为他们后续的表达和评估建立共同的语言基础，这正是目标6010的核心。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9035, 1012, 6008, '学生利用平板绘画工具创作一个新的“aa”的例子，完成后，录制一段简短的音频，向同伴解释他/她的作品为什么是一个“aa”的例子。', '[\"学生在平板上创作的“aa”作品。\", \"学生解释其作品关键属性的音频文件。\"]', '[\"创作的例子在视觉上符合“aa”的主要特征。\", \"口头解释能够阐明至少一个关键属性。\", \"解释清晰，能让听众理解其创作思路。\"]', '此任务让学生创造性地应用他们对“aa”的理解，并通过个人化的表达方式（绘画+口头解释）来巩固概念，有效评估目标6008。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9036, 1012, 6012, '当一名同学展示其为“aa”创作的画作时，其他学生需要在练习本上写下一句反馈，必须使用句型“我注意到……，因为……”。', '[\"学生在练习本上写下的完整反馈句子。\", \"学生口头向同伴反馈时的录音。\"]', '[\"反馈必须是一个完整的句子，并严格遵循“我注意到……，因为……”的句型。\", \"“我注意到”部分是对同伴作品的具体观察。\", \"“因为”部分提供了支持该观察的理由或证据。\"]', '通过结构化的句型，评估学生是否能够为同伴提供具体的、有建设性的反馈，从而提升课堂互动质量，直接对应目标6012。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9037, 1013, 6013, '在计算机环境中完成一次“AI是什么”的探究：(1)提出2个可检验的猜想（例如“AI能/不能做什么”）；(2)使用教师提供的资源或课堂允许的工具收集至少2条证据（如截图、文字摘录或观察记录）；(3)用一句话给出自己的临时结论；(4)说明如果证据发生变化，结论会怎样调整。', '[\"学生提出的2个猜想文本\", \"收集到的2条证据（截图/摘录/观察记录）\", \"一句临时结论\", \"对结论可能变化的简短说明\"]', '[\"猜想明确且可被证据检验\", \"证据来源可追溯并与猜想相关\", \"结论与所给证据一致或能解释不一致\", \"能指出证据变化对结论的影响\"]', '采用探究式评价而非记忆题：让学生在设备环境下围绕核心问题自主生成猜想、寻找证据并形成结论，既符合课堂条件，也避免AI直接给出答案，从而保护学生的判断与推理过程。', 'REVISE', 1, 2, '2026-09-08 14:58:49');

-- ----------------------------
-- Table structure for project_objective
-- ----------------------------
DROP TABLE IF EXISTS `project_objective`;
CREATE TABLE `project_objective`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '目标ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学习目标',
  `sequence_no` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序',
  `standard_refs_json` json NULL COMMENT '对应课程标准ID',
  `literacy_refs_json` json NULL COMMENT 'AI素养ID',
  `rationale` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '推荐理由',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AI' COMMENT 'AI/TEACHER',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ACCEPT/REVISE/REJECT',
  `confirmed` tinyint NOT NULL DEFAULT 0 COMMENT '是否确认',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_objective_project`(`project_id` ASC, `sequence_no` ASC) USING BTREE,
  INDEX `idx_project_objective_confirmed`(`project_id` ASC, `confirmed` ASC) USING BTREE,
  CONSTRAINT `fk_project_objective_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 6014 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目学习目标表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_objective
-- ----------------------------
INSERT INTO `project_objective` VALUES (6001, 1001, '学生能够识别生成式AI回答中需要进一步核验的信息，并说明为什么需要核验。', 1, '[2001, 2002]', '[3001, 3002]', '与信息真实性判断和AI能力边界相关。', 'AI', 'ACCEPT', 1, 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35');
INSERT INTO `project_objective` VALUES (6002, 1001, '学生能够使用至少两个信息来源核验AI生成内容，并依据证据形成可信度判断。', 2, '[2001]', '[3002]', '目标要求学生真正执行信息核验，而非只记忆AI概念。', 'AI', 'REVISE', 1, 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35');
INSERT INTO `project_objective` VALUES (6003, 1001, '学生能够比较自己、同伴与AI的观点，并解释最终接受、修改或拒绝AI建议的理由。', 3, '[2002]', '[3003]', '强调学生保留最终判断责任。', 'AI', 'ACCEPT', 1, 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35');
INSERT INTO `project_objective` VALUES (6004, 1010, '111', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-06 11:59:49', '2026-09-06 11:59:57');
INSERT INTO `project_objective` VALUES (6005, 1011, '123', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-06 17:02:15', '2026-09-06 17:02:17');
INSERT INTO `project_objective` VALUES (6006, 1012, '通过课堂讨论与教师引导，明确话题“aa”的学习范围，并用自己的话定义至少两个“aa”的关键特征。', 1, '[]', '[]', '在主题模糊且学生零基础的情况下，首先帮助学生共同澄清学习对象，建立对“aa”的基本共识，为后续活动奠定语言与认知基础。', 'AI', 'ACCEPT', 1, 1, '2026-09-07 17:23:20', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6007, 1012, '在教师提供的结构化示例中，识别并记录属于“aa”和不属于“aa”的实例各至少两个，用简单理由进行说明。', 2, '[]', '[]', '通过正例与反例对比，训练学生初步判断与分类能力，解决因缺少清晰示例而导致的理解困难。', 'AI', NULL, 1, 1, '2026-09-07 17:23:20', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6008, 1012, '利用平板绘制或口头描述，创作一个符合“aa”特征的新例子，并向同伴解释其关键属性。', 3, '[]', '[]', '在大班额条件下，借助平板进行个别表达，提高每位学生的参与度，同时巩固对“aa”概念的创造性理解。', 'AI', NULL, 1, 1, '2026-09-07 17:23:20', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6009, 1012, '通过观察教师提供的3个与“aa”相关的明确示例，学生能够列出至少2条共同特征，并用自己的话给出一个简单定义。', 1, '[]', '[]', '主题“aa”过于模糊，先提供有限且清晰的实例有助于二年级学生建立基本概念框架，降低因不明确导致的注意力分散。', 'AI', NULL, 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6010, 1012, '在教师引导下，学生能够说出或写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状）。', 2, '[]', '[]', '零基础且话题未界定，聚焦核心词汇可为后续表达与评估奠定共同语言基础。', 'AI', NULL, 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6011, 1012, '使用平板中的简易绘图工具，每位学生独立完成一幅包含“aa”主要特征的草图，并在全班展示时口头说明1条所画特征。', 3, '[]', '[]', '在大班额和时间受限条件下，个体产出与简短分享能保证每生参与并便于教师快速评价理解程度。', 'AI', 'ACCEPT', 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:49');
INSERT INTO `project_objective` VALUES (6012, 1012, '当同伴展示作品时，学生能够运用给定句型“我注意到……，因为……”提出一条具体反馈。', 4, '[]', '[]', '缺乏清晰示例及表达机会受限，结构化句型支持二年级学生进行有效同伴反馈，提升课堂互动质量。', 'AI', NULL, 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6013, 1013, '暂无', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-08 14:53:23', '2026-09-08 14:53:24');

-- ----------------------------
-- Table structure for project_pedagogy
-- ----------------------------
DROP TABLE IF EXISTS `project_pedagogy`;
CREATE TABLE `project_pedagogy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `primary_method_id` bigint UNSIGNED NULL DEFAULT NULL,
  `secondary_method_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '辅助教学法',
  `rationale` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '推荐理由',
  `suitable_for_json` json NULL COMMENT '适用目标',
  `risk_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '风险',
  `alternative_json` json NULL COMMENT '备选方案',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ACCEPT/REVISE',
  `confirmed` tinyint NOT NULL DEFAULT 0 COMMENT '是否确认',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `custom_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `custom_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_pedagogy_project`(`project_id` ASC, `confirmed` ASC) USING BTREE,
  INDEX `idx_project_pedagogy_primary_method`(`primary_method_id` ASC) USING BTREE,
  INDEX `idx_project_pedagogy_secondary_method`(`secondary_method_id` ASC) USING BTREE,
  CONSTRAINT `fk_project_pedagogy_primary_method` FOREIGN KEY (`primary_method_id`) REFERENCES `pedagogy_method` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_project_pedagogy_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_project_pedagogy_secondary_method` FOREIGN KEY (`secondary_method_id`) REFERENCES `pedagogy_method` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 7005 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目教学法决策表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_pedagogy
-- ----------------------------
INSERT INTO `project_pedagogy` VALUES (7001, 1001, 4001, 4005, '以探究式学习组织信息核验过程，以协作学习支持不同证据和判断的比较。', '[6001, 6002, 6003]', '需避免学生在形成初步判断前直接复制AI答案。', '{\"note\": \"DEMO备选：问题式学习 + 协作学习\", \"primaryMethodId\": 4003, \"secondaryMethodId\": 4005}', 'ACCEPT', 1, 1, '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_pedagogy` VALUES (7002, 1010, 4001, NULL, '围绕问题提出猜想、收集证据、比较解释并形成结论。', '[6004]', NULL, '{\"recommended\": {\"name\": \"证据驱动的问题探究\", \"methodId\": 4001, \"rationale\": \"围绕真实信息判断任务组织学生搜集、比较并解释证据，支持已确认目标。\", \"components\": [\"真实问题情境\", \"小组协作\", \"多来源核验\", \"证据比较\", \"反思修订\"]}, \"alternatives\": [{\"name\": \"项目式学习\", \"methodId\": 4002, \"rationale\": \"围绕真实项目产出组织较长周期的学习活动。\", \"components\": [\"问题任务\", \"同伴讨论\", \"反思总结\"]}, {\"name\": \"问题式学习\", \"methodId\": 4003, \"rationale\": \"以复杂问题作为知识学习和问题解决的组织核心。\", \"components\": [\"问题任务\", \"同伴讨论\", \"反思总结\"]}]}', 'ACCEPT', 1, 2, '2026-09-06 11:59:57', NULL, NULL, 'AI');
INSERT INTO `project_pedagogy` VALUES (7003, 1012, NULL, NULL, '针对主题“aa”模糊且学生零基础的情境，采用探究式学习能有效引导学生通过提出问题、观察示例、比较解释来共同构建对“aa”的基本共识和定义，符合目标中澄清概念、识别特征和分类判断的需求。', '[6006, 6009, 6007, 6010, 6008, 6011, 6012]', NULL, '{\"recommended\": {\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"针对主题“aa”模糊且学生零基础的情境，采用探究式学习能有效引导学生通过提出问题、观察示例、比较解释来共同构建对“aa”的基本共识和定义，符合目标中澄清概念、识别特征和分类判断的需求。\", \"components\": [\"提出关于“aa”的核心问题以激发思考\", \"提供3个明确正例与2个反例作为探究证据\", \"小组讨论并比较实例间的共同特征与差异\", \"归纳“aa”的关键属性并形成初步定义\"]}, \"alternatives\": [{\"name\": \"协作学习\", \"methodId\": 4005, \"rationale\": \"在大班额（42人）条件下，利用协作学习促进同伴互动，可高效实现目标中的课堂讨论、共同产出词汇表及结构化反馈练习，确保每位学生的参与度。\", \"components\": [\"个人独立构思“aa”的特征或例子\", \"小组内分享观点并进行证据比较\", \"协商整合出小组的“aa”定义或词汇列表\", \"运用给定句型进行同伴作品反馈\"]}]}', NULL, 0, 3, '2026-09-07 17:30:23', '暂无', '111', 'TEACHER');
INSERT INTO `project_pedagogy` VALUES (7004, 1013, 4001, NULL, '三年级学生首次接触“认识AI”主题，探究式学习允许学生在计算机环境下围绕“AI是什么”这一核心问题自主提出猜想、收集证据并形成结论，既契合设备条件，又避免AI过早提供完整答案，保护学生判断过程。', '[6013]', NULL, '{\"recommended\": {\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"三年级学生首次接触“认识AI”主题，探究式学习允许学生在计算机环境下围绕“AI是什么”这一核心问题自主提出猜想、收集证据并形成结论，既契合设备条件，又避免AI过早提供完整答案，保护学生判断过程。\", \"components\": [\"提出问题：AI能做什么、如何判断机器是否智能？\", \"初步判断：学生写下自己对AI能力的猜想\", \"搜集证据：使用给定示例或在线演示观察AI行为\", \"比较解释：小组讨论观察到的现象与最初猜想的差异\", \"形成结论：全班汇总对AI基本特征的理解\"]}, \"alternatives\": [{\"name\": \"情境体验式学习\", \"methodId\": 4004, \"rationale\": \"通过情境进入和即时体验让学生直观感受AI应用，适合缺乏先备知识的三年级学生，并能在后续反思环节巩固概念。\", \"components\": [\"情境进入：教师展示一段AI语音助手日常对话视频\", \"体验：学生分组与简易聊天机器人交互并记录反应\", \"观察：比较人机对话差异，关注语气、准确度等\", \"解释：教师引导学生归纳AI工作方式的简化模型\", \"应用：设计一个“如果我有AI助手”的小场景\"]}, {\"name\": \"协作学习\", \"methodId\": 4005, \"rationale\": \"利用同伴互动促进观点比较，帮助三年级学生在探索AI时相互启发，防止个别学生或AI工具主导讨论。\", \"components\": [\"个人思考：每名学生列出自己知道或猜测的AI例子\", \"小组分享：轮流介绍并合并重复项\", \"证据比较：小组决定哪些例子最可能属于AI应用\", \"协商：就争议点（如游戏NPC是否算AI）达成组内共识\", \"共同产出：制作“我们的AI列表”海报\"]}]}', 'ACCEPT', 1, 1, '2026-09-08 14:54:31', NULL, NULL, 'AI');

-- ----------------------------
-- Table structure for quality_check
-- ----------------------------
DROP TABLE IF EXISTS `quality_check`;
CREATE TABLE `quality_check`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `check_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检查类型',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PASS/ATTENTION/REVISION_REQUIRED',
  `issue` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '问题',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原因',
  `suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '修改建议',
  `evidence_json` json NULL COMMENT '判断证据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_quality_check_project_status`(`project_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_quality_check_type`(`project_id` ASC, `check_type` ASC) USING BTREE,
  CONSTRAINT `fk_quality_check_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 12005 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教学智检结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quality_check
-- ----------------------------
INSERT INTO `quality_check` VALUES (12001, 1001, 'STANDARD_ALIGNMENT', 'PASS', NULL, 'DEMO检查：学习目标与当前固定Demo课程标准条目在信息判断方向上保持一致。', NULL, '{\"standardIds\": [2001, 2002], \"objectiveIds\": [6001, 6002, 6003]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12002, 1001, 'OBJECTIVE_ACTIVITY', 'PASS', NULL, 'DEMO检查：目标要求的识别、核验和比较行为均在活动链中出现。', NULL, '{\"activityIds\": [8001, 8002, 8003, 8004, 8005]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12003, 1001, 'OBJECTIVE_ASSESSMENT', 'PASS', NULL, 'DEMO检查：三个核心学习目标均至少有一个对应评价任务。', NULL, '{\"assessmentIds\": [9001, 9002, 9003]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12004, 1001, 'EVIDENCE_FIDELITY', 'ATTENTION', '部分证据为固定Demo数据，不可作为正式研究证据。', '当前数据库中的Evidence Card仅用于开发联调，不代表真实文献。', '正式上线前必须替换为经过人工审核的真实研究证据及原始支持文本。', '{\"demoOnly\": true, \"evidenceIds\": [5001, 5002, 5003]}', '2026-08-25 15:00:35');

-- ----------------------------
-- Table structure for research_analysis
-- ----------------------------
DROP TABLE IF EXISTS `research_analysis`;
CREATE TABLE `research_analysis`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '研究分析ID',
  `resource_id` bigint UNSIGNED NULL DEFAULT NULL,
  `project_id` bigint UNSIGNED NOT NULL COMMENT '所属课程设计项目ID',
  `participants_json` json NULL COMMENT '研究对象：学段、年级、样本量、描述等',
  `research_topic` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '研究主题',
  `ai_literacy_json` json NULL COMMENT 'AI素养维度',
  `teaching_strategies_json` json NULL COMMENT '研究中采用的教学策略',
  `intervention_json` json NULL COMMENT '干预时间、课时、周期等',
  `assessment_tools_json` json NULL COMMENT '研究中使用的评价工具',
  `main_findings_json` json NULL COMMENT '主要研究结果',
  `limitations_json` json NULL COMMENT '研究局限',
  `agent_summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '系统/AI形成的研究综合说明，当前Mock阶段可为空',
  `agent_raw_json` json NULL COMMENT '模型原始结构化输出，当前Mock阶段可为空',
  `field_sources_json` json NULL COMMENT '字段来源，例如TEACHER/MOCK/AI，用于保护教师人工修改',
  `readiness_score` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '证据卡信息完整度，0-100，仅用于展示',
  `readiness_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INCOMPLETE' COMMENT '证据卡准备状态：INCOMPLETE/READY',
  `teacher_confirmed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '教师是否确认当前结构化研究解析：0否，1是',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '分析版本号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `structured_data_json` json NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'VALIDATED',
  `teacher_confirmed_at` datetime NULL DEFAULT NULL,
  `session_id` bigint UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_research_analysis_session_version`(`session_id` ASC, `version` ASC) USING BTREE,
  INDEX `idx_research_analysis_resource`(`resource_id` ASC) USING BTREE,
  INDEX `idx_research_analysis_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_research_analysis_readiness`(`project_id` ASC, `readiness_status` ASC) USING BTREE,
  INDEX `idx_research_analysis_confirmed`(`resource_id` ASC, `teacher_confirmed` ASC) USING BTREE,
  INDEX `idx_research_analysis_session_status`(`session_id` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_research_analysis_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_analysis_resource` FOREIGN KEY (`resource_id`) REFERENCES `research_resource` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_analysis_session` FOREIGN KEY (`session_id`) REFERENCES `research_chat_session` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联研究资源结构化解析表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of research_analysis
-- ----------------------------
INSERT INTO `research_analysis` VALUES (2, 2, 1001, '{\"grade\": \"五、六年级\", \"sampleSize\": 84, \"description\": \"小学高年级学生，DEMO样本84人\", \"educationStage\": \"PRIMARY\"}', '生成式AI回答的信息核验与证据判断', '[\"INFORMATION_VERIFICATION\", \"AI_COGNITION\", \"HUMAN_AI_INTERACTION\"]', '[{\"name\": \"先判断后咨询\", \"description\": \"学生在查看AI建议前先形成个人初步判断\"}, {\"name\": \"多来源核验\", \"description\": \"至少使用两个独立信息来源核验AI生成内容\"}, {\"name\": \"同伴证据比较\", \"description\": \"在小组中比较证据并解释观点差异\"}, {\"name\": \"基于证据修订判断\", \"description\": \"根据核验结果接受、修改或拒绝AI建议\"}]', '{\"duration\": \"4周\", \"sessions\": 8, \"description\": \"每周2课时，共8课时的DEMO课堂干预\"}', '[\"信息核验表现任务\", \"证据记录单\", \"课堂观察\", \"学生反思\"]', '[\"学生在多来源信息核验与证据说明方面表现出较明显改善。\", \"先形成个人判断再接触AI建议，有助于学生识别AI回答与已有证据之间的不一致。\", \"要求学生说明“依据什么证据做出判断”，比只要求回答“可信/不可信”更能呈现其核验过程。\"]', '[\"DEMO样本来自单一学校，外部推广需谨慎。\", \"干预仅持续4周，尚不能说明长期保持与迁移效果。\", \"不同AI工具和信息来源质量可能影响学习表现。\"]', '当前DEMO研究与项目“AI的答案可信吗？”高度匹配。可将核心研究启示概括为：先判断、再咨询AI；要求多来源核验；让学生公开证据并修订判断。教学中需要提供可理解的信息来源、证据记录支架和充分的同伴讨论时间。', '{\"note\": \"Synthetic demo data. Not a real publication.\", \"version\": \"v2\", \"provider\": \"DEMO_SEED\"}', '{\"limitations\": \"TEACHER_CONFIRMED\", \"intervention\": \"TEACHER_CONFIRMED\", \"mainFindings\": \"TEACHER_CONFIRMED\", \"participants\": \"TEACHER_CONFIRMED\", \"researchTopic\": \"TEACHER_CONFIRMED\", \"assessmentTools\": \"TEACHER_CONFIRMED\", \"teachingStrategies\": \"TEACHER_CONFIRMED\", \"aiLiteracyDimensions\": \"TEACHER_CONFIRMED\"}', 100, 'READY', 1, 2, '2026-09-03 19:26:37', '2026-09-03 19:26:37', '{\"limitations\": [\"单一学校样本\", \"干预周期较短\", \"工具与来源质量可能影响结果\"], \"mainFindings\": [\"多来源核验促进学生关注信息依据\", \"先形成观点后咨询AI有助于识别信息不一致\", \"公开说明证据有助于呈现和修订判断过程\"], \"evidenceReady\": true, \"sourceExcerpt\": \"学生先形成初步判断，再通过至少两个信息来源核验AI回答，并在小组中依据证据修订结论。\", \"researchTopics\": [\"生成式AI信息核验\", \"证据判断\"], \"assessmentTools\": [\"信息核验表现任务\", \"证据记录单\", \"课堂观察\", \"学生反思\"], \"researchSubjects\": [\"小学五、六年级学生\", \"DEMO样本84人\"], \"teachingStrategies\": [\"先判断后咨询\", \"多来源核验\", \"同伴证据比较\", \"基于证据修订判断\"], \"aiLiteracyDimensions\": [\"信息核验\", \"AI认知\", \"人机有效交互\"], \"interventionDuration\": \"4周，共8课时\", \"teachingImplications\": \"在五年级AI信息核验课程中，可设计“初步判断—AI比较—多来源核验—小组证据讨论—修订结论”的学习链，并要求学生记录证据与最终判断之间的关系。\"}', 'VALIDATED', '2026-09-03 19:30:00', NULL);
INSERT INTO `research_analysis` VALUES (3, 3, 1001, '{\"grade\": \"小学高年级\", \"sampleSize\": 56, \"description\": \"DEMO样本56人\", \"educationStage\": \"PRIMARY\"}', '同伴讨论与生成式AI批判性判断', '[\"INFORMATION_VERIFICATION\", \"HUMAN_AI_INTERACTION\"]', '[{\"name\": \"对比AI解释\", \"description\": \"比较不同AI生成解释中的共同点与冲突\"}, {\"name\": \"同伴证据讨论\", \"description\": \"小组成员依据证据解释判断差异\"}]', NULL, '[\"课堂讨论记录\", \"判断理由评分量表\"]', '[\"同伴讨论能够使部分学生更主动地说明自己的证据来源。\", \"当不同AI回答出现冲突时，学生更可能提出进一步核验需求。\"]', '[]', '当前资料已识别研究对象、主题、AI素养、两项教学策略和部分结果；干预时间及研究局限仍未确认，暂不生成正式证据卡。', '{\"note\": \"Incomplete synthetic demo record.\", \"version\": \"v2\", \"provider\": \"DEMO_SEED\"}', '{\"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 75, 'INCOMPLETE', 0, 1, '2026-09-03 19:26:37', '2026-09-03 19:26:37', '{\"limitations\": [], \"mainFindings\": [\"同伴讨论促进证据说明\", \"AI回答冲突促进进一步核验\"], \"evidenceReady\": false, \"researchTopics\": [\"同伴讨论\", \"生成式AI批判性判断\"], \"assessmentTools\": [\"课堂讨论记录\", \"判断理由评分量表\"], \"researchSubjects\": [\"小学高年级学生\", \"DEMO样本56人\"], \"teachingStrategies\": [\"对比AI解释\", \"同伴证据讨论\"], \"aiLiteracyDimensions\": [\"信息核验\", \"人机有效交互\"], \"interventionDuration\": null}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (4, NULL, 1013, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:54:55', '2026-09-08 12:54:55', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 7);
INSERT INTO `research_analysis` VALUES (6, NULL, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:56:50', '2026-09-08 12:56:50', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 3);
INSERT INTO `research_analysis` VALUES (7, NULL, 1001, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:56:50', '2026-09-08 12:56:50', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 8);
INSERT INTO `research_analysis` VALUES (8, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 18:53:24', '2026-09-08 18:53:24', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\", \"The relationship between GAI use and student demographics\", \"The relationship between GAI use and personality traits (Big Five)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (9, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 2, '2026-09-08 18:54:20', '2026-09-08 18:54:20', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI_COGNITION\"]}', 'VALIDATED', NULL, NULL);
