  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `project_id` bigint UNSIGNED NOT NULL,
  `user_id` bigint UNSIGNED NOT NULL,
  `mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'COURSE_GENERATE',
  `selected_types_json` json NULL,
  `common_settings_json` json NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `current_step` tinyint UNSIGNED NOT NULL DEFAULT 1,
  `resource_settings_json` json NULL,
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_resource_creation_job_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_resource_creation_job_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_resource_creation_job_project_status`(`project_id` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_resource_creation_job_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_resource_creation_job_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_resource_creation_job_mode` CHECK (`mode` in (_utf8mb4'COURSE_GENERATE',_utf8mb4'RESOURCE_ADAPT'))
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

